def _clean_idempotency_key(idempotency_key: str) -> str:
    if not isinstance(idempotency_key, str):
        raise ValidationError("idempotency_key must be a string")
    cleaned = idempotency_key.strip()
    if not cleaned:
        raise ValidationError("idempotency_key must be non-empty")
    if len(cleaned) > MAX_IDEMPOTENCY_KEY_LENGTH:
        raise ValidationError(
