"""Tenant-isolated, parameterized ledger query builders for the Meko platform."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, FrozenSet, Tuple

ALLOWED_SCOPES: FrozenSet[str] = frozenset(
    {"ledger:read", "ledger:write", "webhook:admin", "migration:approve"}
)

Query = Tuple[str, Tuple[Any, ...]]


class TenantMismatchError(Exception):
    """Raised when tenant context is missing or disagrees with authentication."""


class AuthorizationError(PermissionError):
    """Raised when an auth context lacks a required scope or holds an invalid one."""


@dataclass(frozen=True)
class AuthContext:
    actor_id: str
    tenant_id: str
    scopes: FrozenSet[str]

    def __post_init__(self) -> None:
        actor = (self.actor_id or "").strip()
        tenant = (self.tenant_id or "").strip()
        if not actor:
            raise AuthorizationError("Missing authenticated actor_id")
        if not tenant:
            raise TenantMismatchError("Missing authenticated tenant_id")

        raw = self.scopes
        if raw is None or isinstance(raw, str):
            raise AuthorizationError("scopes must be a collection of scope strings")
        scopes = frozenset(str(scope).strip() for scope in raw)
        if "*" in scopes:
            raise AuthorizationError("Wildcard scopes are not permitted")
        invalid = scopes - ALLOWED_SCOPES
        if invalid:
            raise AuthorizationError(f"Unknown scopes: {sorted(invalid)}")

        object.__setattr__(self, "actor_id", actor)
        object.__setattr__(self, "tenant_id", tenant)
        object.__setattr__(self, "scopes", scopes)


def enforce_tenant(auth_ctx: AuthContext, request_tenant_id: str | None) -> str:
    if not isinstance(auth_ctx, AuthContext):
        raise TypeError("auth_ctx must be an AuthContext")
    tenant = (auth_ctx.tenant_id or "").strip()
    if not tenant:
        raise TenantMismatchError("Missing authenticated tenant_id")
    if request_tenant_id is not None:
        requested = str(request_tenant_id).strip()
        if not requested:
            raise TenantMismatchError("Blank request tenant_id")
        if requested != tenant:
            raise TenantMismatchError(
                "Request tenant_id does not match authenticated context"
            )
    return tenant


def require_scope(auth_ctx: AuthContext, scope: str) -> None:
    if scope not in ALLOWED_SCOPES:
        raise AuthorizationError(f"Unsupported scope: {scope}")
    if "*" in auth_ctx.scopes or scope not in auth_ctx.scopes:
        raise AuthorizationError(f"Missing required scope: {scope}")


def build_ledger_queries(auth_ctx: AuthContext, entry_id: str) -> Tuple[Query, Query]:
    tenant_id = enforce_tenant(auth_ctx, None)
    require_scope(auth_ctx, "ledger:read")

    entry = str(entry_id or "").strip()
    if not entry:
        raise ValueError("entry_id is required")

    entry_sql = (
        "SELECT id, tenant_id, reference_id, status, currency, amount_minor, created_at "
        "FROM journal_entries "
        "WHERE tenant_id = %s AND id = %s"
    )
    lines_sql = (
        "SELECT id, tenant_id, entry_id, account_id, direction, amount_minor, created_at "
        "FROM journal_lines "
        "WHERE tenant_id = %s AND entry_id = %s "
        "ORDER BY id"
    )

    return (entry_sql, (tenant_id, entry)), (lines_sql, (tenant_id, entry))
