"""Default-deny RBAC scope guard (ADR-006.2).

Every guard call must name an exact, allow-listed scope. Missing/empty
requirements, wildcards, and unknown scopes are denied outright.
"""

from __future__ import annotations

from typing import Any, FrozenSet

ALLOWED_SCOPES: FrozenSet[str] = frozenset(
    {
        "ledger:read",
        "ledger:write",
        "webhook:admin",
        "migration:approve",
    }
)

_WILDCARD = "*"


class PermissionDeniedError(Exception):
    """Raised when an actor does not hold an explicit, valid scope grant."""


def _granted_scopes(auth_ctx: Any) -> FrozenSet[str]:
    """Return the actor's verified grants; anything unusable means no grants."""
    scopes = getattr(auth_ctx, "scopes", None)
    if not scopes:
        return frozenset()
    return frozenset(scopes)


def require_scope(auth_ctx: Any, required_scope: str) -> None:
    """Enforce `required_scope` against `auth_ctx`; deny by default.

    Raises PermissionDeniedError when the requirement is absent/empty, not an
    exact member of ALLOWED_SCOPES, a wildcard, or not granted to the actor.
    Role fallbacks are never consulted, so they cannot bypass enforcement.
    """
    if not required_scope:
        raise PermissionDeniedError("Explicit scope required; default deny.")

    if required_scope == _WILDCARD or required_scope not in ALLOWED_SCOPES:
        raise PermissionDeniedError(
            f"Scope {required_scope!r} is not a valid system scope."
        )

    granted = _granted_scopes(auth_ctx)

    if _WILDCARD in granted:
        raise PermissionDeniedError("Wildcard scope grants are not permitted.")

    if required_scope not in granted:
        raise PermissionDeniedError(f"Missing required scope: {required_scope}")
