-- 0003_journal_entries_fee_minor.sql
-- Forward-only, zero-downtime migration per ADR-001.1 / ADR-001.2 / ADR-001.3.
-- No CREATE/DROP INDEX CONCURRENTLY here, so -- migrate:no-transaction (NO_TX) marker is not required.

SET lock_timeout = '2s';
SET statement_timeout = '30s';

-- Phase 1: additive column with a constant DEFAULT only (PG11+ fast default).
-- The default is stored in attmissingval, so there is no table rewrite and no scan;
-- existing rows read as 0 immediately. Kept nullable on purpose for Phase 4.
ALTER TABLE journal_entries
    ADD COLUMN IF NOT EXISTS fee_minor BIGINT DEFAULT 0;

-- Phase 2: backfill safety net for legacy writers that may have inserted explicit NULLs.
-- On a fast-default column this normally touches zero rows. On very large tables, run
-- this as a separate batched worker backfill per KB #6 instead of inline.
UPDATE journal_entries
   SET fee_minor = 0
 WHERE fee_minor IS NULL;

-- Phase 3: two-phase CHECK constraint - add NOT VALID (metadata-only, brief lock), then validate.
DO $$
BEGIN
    ALTER TABLE journal_entries
        ADD CONSTRAINT chk_fee_nonnegative CHECK (fee_minor >= 0) NOT VALID;
EXCEPTION
    WHEN duplicate_object THEN NULL;
END $$;

ALTER TABLE journal_entries
    VALIDATE CONSTRAINT chk_fee_nonnegative;

-- Phase 4: enforce NOT NULL without a full-table scan.
-- A validated CHECK (fee_minor IS NOT NULL) lets PG12+ skip the seq scan in SET NOT NULL.
DO $$
BEGIN
    ALTER TABLE journal_entries
        ADD CONSTRAINT chk_fee_nonnull CHECK (fee_minor IS NOT NULL) NOT VALID;
EXCEPTION
    WHEN duplicate_object THEN NULL;
END $$;

ALTER TABLE journal_entries
    VALIDATE CONSTRAINT chk_fee_nonnull;

ALTER TABLE journal_entries
    ALTER COLUMN fee_minor SET NOT NULL;

ALTER TABLE journal_entries
    ALTER COLUMN fee_minor SET DEFAULT 0;

-- Phase 5: drop the temporary proof constraint used to make SET NOT NULL scan-free.
ALTER TABLE journal_entries
    DROP CONSTRAINT IF EXISTS chk_fee_nonnull;
