    """Strict Unix-seconds parse: ASCII digits only, no signs, floats, underscores."""
    if not isinstance(raw, str):
        return None
    candidate = raw.strip()
    if not candidate or not candidate.isascii() or not candidate.isdigit():
        return None
    try:
        return int(candidate)
    except ValueError:  # pragma: no cover - int digit limit on absurdly long inputs
        return None


def _parse_signatures(raw: object) -> list[bytes]:
    """Extract v1 digests from the signature header, skipping malformed tokens."""
    if not isinstance(raw, str):
        return []
