    for token in raw.replace(",", " ").split():
        if not token.lower().startswith(SIGNATURE_SCHEME):
            continue
        try:
            digest = bytes.fromhex(token[len(SIGNATURE_SCHEME) :].strip())
        except ValueError:
            continue
        if len(digest) == DIGEST_SIZE:
            digests.append(digest)
    return digests


