        if not isinstance(account_id, str) or not account_id.strip():
            raise ValidationError("account_id must be a non-empty string")
        object.__setattr__(self, "account_id", account_id.strip())

        direction = self.direction
        if isinstance(direction, Direction):
            normalized_direction = direction
        elif isinstance(direction, str):
            try:
                normalized_direction = Direction(direction.strip().upper())
            except ValueError:
                raise ValidationError(
                    "direction must be either 'DEBIT' or 'CREDIT'"
                ) from None
        else:
            raise ValidationError("direction must be either 'DEBIT' or 'CREDIT'")
        object.__setattr__(self, "direction", normalized_direction)

        amount_minor = self.amount_minor
        if isinstance(amount_minor, bool) or not isinstance(amount_minor, int):
            raise ValidationError("amount_minor must be an integer minor-unit amount")
        if amount_minor <= 0:
            raise ValidationError("amount_minor must be greater than zero")
        object.__setattr__(self, "amount_minor", int(amount_minor))


@dataclass(frozen=True)
class TransferResult:
    journal_id: str
    tenant_id: str
    operation: str
    currency: str
    request_hash: str
    lines: Tuple[PostingLine, ...]
    total_debit_minor: int
    total_credit_minor: int
    replayed: bool = False


@dataclass(frozen=True)
class IdempotencyRecord:
    tenant_id: str
    idempotency_key: str
    request_hash: str
    result: TransferResult


class LedgerStore(Protocol):
    def transaction(self) -> ContextManager[None]:
        ...

    def get_idempotency(
        self, tenant_id: str, idempotency_key: str
    ) -> Optional[IdempotencyRecord]:
        ...

    def put_idempotency(self, record: IdempotencyRecord) -> None:
        ...


class InMemoryLedgerStore:
    def __init__(self) -> None:
        self._records: dict[tuple[str, str], IdempotencyRecord] = {}
        self._lock = threading.RLock()

    @contextmanager
    def transaction(self) -> Iterator[None]:
        with self._lock:
            yield

    def get_idempotency(
        self, tenant_id: str, idempotency_key: str
    ) -> Optional[IdempotencyRecord]:
        with self._lock:
            return self._records.get((tenant_id, idempotency_key))

    def put_idempotency(self, record: IdempotencyRecord) -> None:
        with self._lock:
            key = (record.tenant_id, record.idempotency_key)
            if key in self._records:
                raise IdempotencyConflictError(
                    "idempotency_key already exists for this tenant"
                )
            self._records[key] = record


def _normalize_tenant_id(tenant_id: str) -> str:
    if not isinstance(tenant_id, str) or not tenant_id.strip():
        raise ValidationError("tenant_id must be a non-empty string")
    return tenant_id.strip()


def _normalize_idempotency_key(idempotency_key: str) -> str:
    if not isinstance(idempotency_key, str):
        raise ValidationError("idempotency_key must be a string")
    key = idempotency_key.strip()
    if not key:
        raise ValidationError("idempotency_key must be a non-empty string")
    if len(key) > _MAX_IDEMPOTENCY_KEY_LENGTH:
        raise ValidationError(
            f"idempotency_key must be at most {_MAX_IDEMPOTENCY_KEY_LENGTH} characters"
        )
    return key


def _normalize_currency(currency: str) -> str:
    if not isinstance(currency, str):
        raise ValidationError("currency must be a string")
    code = currency.strip().upper()
    if not _CURRENCY_RE.fullmatch(code):
        raise ValidationError("currency must be a 3-letter ISO currency code")
    return code


def _normalize_operation(operation: str) -> str:
    if not isinstance(operation, str) or not operation.strip():
        raise ValidationError("operation must be a non-empty string")
    return operation.strip()


def _coerce_lines(lines: Iterable[PostingLine]) -> Tuple[PostingLine, ...]:
    if isinstance(lines, (str, bytes)):
        raise ValidationError("lines must be an iterable of PostingLine instances")
    try:
        items = tuple(lines)
    except TypeError:
        raise ValidationError(
            "lines must be an iterable of PostingLine instances"
        ) from None
    if not items:
        raise ValidationError("lines must contain at least one PostingLine")
    for index, line in enumerate(items):
        if not isinstance(line, PostingLine):
            raise ValidationError(f"lines[{index}] must be a PostingLine")
    return items


